sys_security_acl.script:
// Role: the compliance team reads every mapping, an owner reads only the mappings they own.
//       Self-contained on purpose: it does not call a Script Include, so it works whatever scope the rule was created in.
answer = gs.hasRole('x_1929776_compli_0.admin') ||
         (!current.getValue('owner') ? false : current.getValue('owner') == gs.getUserID());
